const tabId = 2017691853;

const epDetails = await browserjs(tabId, () => {
  const raw = document.body.innerHTML;
  function getSection(title) {
    const i = raw.indexOf(title);
    if (i === -1) return null;
    const end = raw.indexOf('</div>', i + title.length + 100);
    return raw.slice(i, end).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  }
  return {
    people: getSection("How many people can play?"),
    age: getSection("Is there an age restriction?"),
    duration: getSection("How long does the experience last?"),
  };
});

console.log("Escape Plan details extracted:", epDetails);

