const tabId = 2017691857;

const fullArticle = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h2, h3'));
  const results = {};
  headings.forEach(h => {
    let text = '';
    let curr = h.nextElementSibling;
    while (curr && !['H2', 'H3'].includes(curr.tagName)) {
      text += curr.innerText + '\n';
      curr = curr.nextElementSibling;
    }
    results[h.innerText.trim()] = text.trim();
  });
  return results;
});

console.log("Headings found:", Object.keys(fullArticle));
console.log("Cost section:", fullArticle["How much does F1 Arcade cost?"]);
console.log("Duration section:", fullArticle["How long is F1 Arcade?"]);
console.log("Age section:", fullArticle["Is there a F1 Arcade age limit?"]);

