const tabId = 2017691864;

await tool.navigate({ tabId, url: "https://duckduckgo.com/?q=Sherlock+The+Game+Is+Now+Shepherd%27s+Bush+Tripadvisor" });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });

const results = await browserjs(tabId, () => {
  return Array.from(document.querySelectorAll('a[data-testid="result-title-a"], a.result__a, h2 a')).map(a => ({
    title: a.innerText,
    url: a.href
  })).filter(a => a.url.includes("tripadvisor") && !a.url.includes("ad_domain"));
});

console.log("Sherlock TripAdvisor links:", results);

if (results.length > 0) {
  await tool.navigate({ tabId, url: results[0].url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
}

console.log("Tab 2017691864 title:", await browserjs(tabId, () => document.title));

